    "node": ">=20"
  },
  "packageManager": "pnpm@9.4.0",
  "//overrides": {
    "security": "Patched transitive floors for brace-expansion (GHSA-rgw5-rvv9-x895), js-yaml (GHSA-5p4m-2wfm-xmqj) and nanoid (GHSA-2v37-7h3g-55p8, reached through postcss), browserslist and baseline-browser-mapping (DoS on untrusted input). Keep each override on its existing major line until the dependency tree resolves a safe version without help."
